ALTER POLICY activity_media_enrolled_read ON storage.objects USING (bucket_id='activity-media' AND EXISTS (SELECT 1 FROM public.commerce_enrollments e WHERE e.user_id=auth.uid() AND e.product_id=(storage.foldername(storage.objects.name))[1] AND e.status='active' AND (e.expires_at IS NULL OR e.expires_at>now())) AND EXISTS (SELECT 1 FROM public.learning_activity_staff s WHERE s.video_path=storage.objects.name OR s.video_poster_path=storage.objects.name));
COMMENT ON TABLE public.learning_activity_materials IS 'Pre-delivery material metadata; original files are admin/service readable only. Learners download personalized copies through authenticated server functions. Answer keys stay in learning_answers.';